from __future__ import annotations

import hashlib
import json
import os
import shutil
from pathlib import Path
from typing import Any, Mapping


_RECEIPT_SCHEMA = "eira2_native_voice_asset_takeover_v1"
_DEFAULT_MODEL_NAME = "en_US-hfc_female-medium.onnx"


def _sha256(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def _atomic_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".new")
    temporary.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.chmod(temporary, 0o600)
    os.replace(temporary, path)


def _reject_symlinked_relative_path(root: Path, path: Path, code: str) -> None:
    """Reject symlink components below an already-resolved EIRA2 runtime root."""
    try:
        relative = path.relative_to(root)
    except ValueError as error:
        raise RuntimeError(code) from error
    cursor = root
    for part in relative.parts:
        cursor = cursor / part
        if cursor.is_symlink():
            raise RuntimeError(code)


def canonical_native_voice_model(runtime_root: Path) -> Path:
    root = runtime_root.expanduser().resolve()
    return root / "var" / "voice" / "voices" / _DEFAULT_MODEL_NAME


def canonical_native_voice_config(runtime_root: Path) -> Path:
    return Path(str(canonical_native_voice_model(runtime_root)) + ".json")


def native_voice_asset_receipt_path(runtime_root: Path) -> Path:
    root = runtime_root.expanduser().resolve()
    return root / "var" / "voice" / "voice-asset-takeover.json"


def _source_config_for(source: Path, source_config: Path | None) -> Path:
    selected = source_config.expanduser() if source_config is not None else Path(str(source) + ".json")
    if selected.is_symlink():
        raise RuntimeError("voice_asset_config_source_symlink_forbidden")
    return selected.resolve()


def _validate_source(path: Path, *, missing_code: str, empty_code: str) -> tuple[str, int]:
    if not path.is_file():
        raise RuntimeError(missing_code)
    size = path.stat().st_size
    if size <= 0:
        raise RuntimeError(empty_code)
    return _sha256(path), size


def _copy_hash_identical(source: Path, destination: Path, expected_sha: str, *, prefix: str) -> None:
    if destination.exists():
        if not destination.is_file():
            raise RuntimeError(prefix + "_destination_not_regular_file")
        if _sha256(destination) != expected_sha:
            raise RuntimeError(prefix + "_destination_conflict")
        os.chmod(destination, destination.stat().st_mode & ~0o111)
        return

    temporary = destination.with_name(destination.name + ".new")
    if temporary.exists() or temporary.is_symlink():
        temporary.unlink()
    try:
        shutil.copyfile(source, temporary)
        os.chmod(temporary, 0o600)
        if _sha256(temporary) != expected_sha:
            raise RuntimeError(prefix + "_staged_hash_mismatch")
        os.replace(temporary, destination)
    finally:
        if temporary.exists() or temporary.is_symlink():
            temporary.unlink()

    os.chmod(destination, destination.stat().st_mode & ~0o111)


def provision_native_voice_asset(
    *,
    runtime_root: Path,
    source: Path,
    source_config: Path | None = None,
    receipt_path: Path | None = None,
) -> dict[str, Any]:
    """Copy a complete Piper voice pair into EIRA2-owned runtime data with hash proof.

    PiperVoice.load(model.onnx) resolves its configuration from model.onnx.json.
    The takeover therefore treats those two files as one required runtime asset set.
    No EIRA1 code is imported or executed, and both source files remain unchanged.
    """
    root_input = runtime_root.expanduser()
    source_input = source.expanduser()
    receipt_input = receipt_path.expanduser() if receipt_path is not None else None

    if root_input.is_symlink():
        raise RuntimeError("voice_asset_runtime_root_symlink_forbidden")
    if source_input.is_symlink():
        raise RuntimeError("voice_asset_source_symlink_forbidden")
    if receipt_input is not None and receipt_input.is_symlink():
        raise RuntimeError("voice_asset_receipt_symlink_forbidden")

    root = root_input.resolve()
    source = source_input.resolve()
    config_source = _source_config_for(source_input, source_config)
    destination = canonical_native_voice_model(root)
    config_destination = canonical_native_voice_config(root)
    receipt_file = (
        receipt_input.resolve()
        if receipt_input is not None
        else native_voice_asset_receipt_path(root)
    )

    if not root.is_dir():
        raise RuntimeError("voice_asset_runtime_root_missing")
    if source == destination or root in source.parents:
        raise RuntimeError("voice_asset_source_must_be_external_to_eira2")
    if config_source == config_destination or root in config_source.parents:
        raise RuntimeError("voice_asset_config_source_must_be_external_to_eira2")
    if receipt_file != native_voice_asset_receipt_path(root):
        if root != receipt_file and root not in receipt_file.parents:
            raise RuntimeError("voice_asset_receipt_must_be_under_eira2")

    _reject_symlinked_relative_path(root, destination, "voice_asset_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, config_destination, "voice_asset_config_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, receipt_file, "voice_asset_receipt_symlink_forbidden")

    source_sha_before, source_size = _validate_source(
        source,
        missing_code="voice_asset_source_must_be_regular_file",
        empty_code="voice_asset_source_empty",
    )
    config_sha_before, config_size = _validate_source(
        config_source,
        missing_code="voice_asset_config_source_must_be_regular_file",
        empty_code="voice_asset_config_source_empty",
    )

    destination.parent.mkdir(parents=True, exist_ok=True)
    _reject_symlinked_relative_path(root, destination, "voice_asset_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, config_destination, "voice_asset_config_destination_symlink_forbidden")

    # Validate any existing pair before writing either member, then stage/copy each.
    if destination.exists() and (
        not destination.is_file() or _sha256(destination) != source_sha_before
    ):
        raise RuntimeError("voice_asset_destination_conflict")
    if config_destination.exists() and (
        not config_destination.is_file() or _sha256(config_destination) != config_sha_before
    ):
        raise RuntimeError("voice_asset_config_destination_conflict")

    _copy_hash_identical(
        source,
        destination,
        source_sha_before,
        prefix="voice_asset",
    )
    _copy_hash_identical(
        config_source,
        config_destination,
        config_sha_before,
        prefix="voice_asset_config",
    )

    destination_sha = _sha256(destination)
    config_destination_sha = _sha256(config_destination)
    source_sha_after = _sha256(source)
    config_sha_after = _sha256(config_source)
    if source_sha_after != source_sha_before:
        raise RuntimeError("voice_asset_source_changed_during_takeover")
    if config_sha_after != config_sha_before:
        raise RuntimeError("voice_asset_config_source_changed_during_takeover")
    if destination_sha != source_sha_before:
        raise RuntimeError("voice_asset_destination_hash_mismatch")
    if config_destination_sha != config_sha_before:
        raise RuntimeError("voice_asset_config_destination_hash_mismatch")
    if destination.stat().st_mode & 0o111:
        raise RuntimeError("voice_asset_destination_executable")
    if config_destination.stat().st_mode & 0o111:
        raise RuntimeError("voice_asset_config_destination_executable")

    receipt: dict[str, Any] = {
        "schema": _RECEIPT_SCHEMA,
        "ok": True,
        "source_path": str(source),
        "source_size": source_size,
        "source_sha256": source_sha_before,
        "source_unchanged": True,
        "config_source_path": str(config_source),
        "config_source_size": config_size,
        "config_source_sha256": config_sha_before,
        "config_source_unchanged": True,
        "destination_path": str(destination),
        "destination_sha256": destination_sha,
        "destination_under_eira2": True,
        "destination_executable": False,
        "config_destination_path": str(config_destination),
        "config_destination_sha256": config_destination_sha,
        "config_destination_under_eira2": True,
        "config_destination_executable": False,
        "complete_piper_voice_pair": True,
        "eira1_code_imported": False,
        "eira1_runtime_delegation": False,
        "model_role": "eira2_owned_runtime_dependency",
    }
    _atomic_json(receipt_file, receipt)
    return receipt


def verify_native_voice_asset(
    *,
    runtime_root: Path,
    receipt_path: Path | None = None,
) -> dict[str, Any]:
    """Fail closed unless the complete canonical EIRA2 Piper voice pair is attested."""
    root_input = runtime_root.expanduser()
    receipt_input = receipt_path.expanduser() if receipt_path is not None else None
    if root_input.is_symlink():
        raise RuntimeError("voice_asset_runtime_root_symlink_forbidden")
    if receipt_input is not None and receipt_input.is_symlink():
        raise RuntimeError("voice_asset_receipt_symlink_forbidden")

    root = root_input.resolve()
    destination = canonical_native_voice_model(root)
    config_destination = canonical_native_voice_config(root)
    receipt_file = (
        receipt_input.resolve()
        if receipt_input is not None
        else native_voice_asset_receipt_path(root)
    )
    if receipt_file != native_voice_asset_receipt_path(root):
        if root != receipt_file and root not in receipt_file.parents:
            raise RuntimeError("voice_asset_receipt_must_be_under_eira2")
    _reject_symlinked_relative_path(root, destination, "voice_asset_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, config_destination, "voice_asset_config_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, receipt_file, "voice_asset_receipt_symlink_forbidden")

    try:
        payload = json.loads(receipt_file.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise RuntimeError("voice_asset_takeover_receipt_unreadable") from error
    if not isinstance(payload, dict):
        raise RuntimeError("voice_asset_takeover_receipt_invalid")
    if payload.get("schema") != _RECEIPT_SCHEMA or payload.get("ok") is not True:
        raise RuntimeError("voice_asset_takeover_receipt_not_qualified")
    if payload.get("complete_piper_voice_pair") is not True:
        raise RuntimeError("voice_asset_complete_piper_pair_not_verified")
    if payload.get("destination_under_eira2") is not True:
        raise RuntimeError("voice_asset_destination_ownership_not_verified")
    if payload.get("config_destination_under_eira2") is not True:
        raise RuntimeError("voice_asset_config_destination_ownership_not_verified")
    if payload.get("destination_executable") is not False:
        raise RuntimeError("voice_asset_destination_execute_policy_invalid")
    if payload.get("config_destination_executable") is not False:
        raise RuntimeError("voice_asset_config_destination_execute_policy_invalid")
    if payload.get("eira1_code_imported") is not False or payload.get("eira1_runtime_delegation") is not False:
        raise RuntimeError("voice_asset_takeover_contains_eira1_runtime_dependency")
    if payload.get("source_unchanged") is not True or payload.get("config_source_unchanged") is not True:
        raise RuntimeError("voice_asset_takeover_source_preservation_not_verified")

    recorded_destination_raw = Path(str(payload.get("destination_path") or "")).expanduser()
    recorded_config_raw = Path(str(payload.get("config_destination_path") or "")).expanduser()
    if recorded_destination_raw.is_symlink():
        raise RuntimeError("voice_asset_takeover_destination_not_canonical")
    if recorded_config_raw.is_symlink():
        raise RuntimeError("voice_asset_takeover_config_destination_not_canonical")
    if recorded_destination_raw.resolve() != destination:
        raise RuntimeError("voice_asset_takeover_destination_not_canonical")
    if recorded_config_raw.resolve() != config_destination:
        raise RuntimeError("voice_asset_takeover_config_destination_not_canonical")

    if not destination.is_file():
        raise RuntimeError("voice_asset_native_model_missing")
    if not config_destination.is_file():
        raise RuntimeError("voice_asset_native_config_missing")
    if destination.stat().st_size <= 0:
        raise RuntimeError("voice_asset_native_model_empty")
    if config_destination.stat().st_size <= 0:
        raise RuntimeError("voice_asset_native_config_empty")
    if destination.stat().st_mode & 0o111:
        raise RuntimeError("voice_asset_native_model_executable")
    if config_destination.stat().st_mode & 0o111:
        raise RuntimeError("voice_asset_native_config_executable")

    recorded_sha = str(payload.get("destination_sha256") or "").strip().casefold()
    recorded_config_sha = str(payload.get("config_destination_sha256") or "").strip().casefold()
    actual_sha = _sha256(destination)
    actual_config_sha = _sha256(config_destination)
    if len(recorded_sha) != 64 or actual_sha != recorded_sha:
        raise RuntimeError("voice_asset_native_model_hash_mismatch")
    if len(recorded_config_sha) != 64 or actual_config_sha != recorded_config_sha:
        raise RuntimeError("voice_asset_native_config_hash_mismatch")

    verified = dict(payload)
    verified["verified_now"] = True
    verified["destination_sha256"] = actual_sha
    verified["config_destination_sha256"] = actual_config_sha
    return verified
